"use client";

import { useEffect, useState } from "react";
import { io, Socket } from "socket.io-client";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { CheckCircle2, RefreshCw } from "lucide-react";
import { MeterWithReading, Reading } from "@/lib/types";

interface SettingsFormProps {
  initialSettings: {
    ratePerKwh: number;
    alarmSetpointKw: number;
    alertSetpointKw: number;
    referenceCapacityKw: number;
  };
  initialMeters: MeterWithReading[];
}

export function SettingsForm({ initialSettings, initialMeters }: SettingsFormProps) {
  const [settings, setSettings] = useState(initialSettings);
  const [meters, setMeters] = useState<MeterWithReading[]>(initialMeters);

  // Local input states for the plant setpoints
  const [ratePerKwh, setRatePerKwh] = useState(initialSettings.ratePerKwh.toString());
  const [alarmSetpointKw, setAlarmSetpointKw] = useState(initialSettings.alarmSetpointKw.toString());
  const [alertSetpointKw, setAlertSetpointKw] = useState(initialSettings.alertSetpointKw.toString());
  const [referenceCapacityKw, setReferenceCapacityKw] = useState(initialSettings.referenceCapacityKw.toString());

  // Local state for meter threshold inputs, mapped by meter ID
  const [thresholds, setThresholds] = useState<Record<number, string>>(
    initialMeters.reduce((acc, m) => {
      acc[m.id] = (m.maxPowerKw ?? 0).toString();
      return acc;
    }, {} as Record<number, string>)
  );

  // Success indicator states
  const [savedSettings, setSavedSettings] = useState(false);
  const [savedThresholds, setSavedThresholds] = useState(false);
  const [savingSettings, setSavingSettings] = useState(false);
  const [savingThresholds, setSavingThresholds] = useState(false);

  // Real-time socket subscription
  useEffect(() => {
    const socket: Socket = io();
    socket.on("reading:new", (reading: Reading) => {
      setMeters((prev) =>
        prev.map((m) => (m.id === reading.meterId ? { ...m, latestReading: reading } : m))
      );
    });
    return () => {
      socket.disconnect();
    };
  }, []);

  // Save plant setpoints
  async function handleSaveSettings(e: React.FormEvent) {
    e.preventDefault();
    setSavingSettings(true);
    setSavedSettings(false);

    try {
      const response = await fetch("/api/settings", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ratePerKwh: parseFloat(ratePerKwh),
          alarmSetpointKw: parseFloat(alarmSetpointKw),
          alertSetpointKw: parseFloat(alertSetpointKw),
          referenceCapacityKw: parseFloat(referenceCapacityKw),
        }),
      });

      if (response.ok) {
        const data = await response.json();
        setSettings(data);
        setSavedSettings(true);
        setTimeout(() => setSavedSettings(false), 2000);
      }
    } catch (error) {
      console.error("Failed to save settings:", error);
    } finally {
      setSavingSettings(false);
    }
  }

  // Save per-equipment thresholds
  async function handleSaveThresholds() {
    setSavingThresholds(true);
    setSavedThresholds(false);

    const thresholdData = Object.entries(thresholds).map(([id, maxPowerKw]) => ({
      id: parseInt(id),
      maxPowerKw: parseFloat(maxPowerKw),
    }));

    try {
      const response = await fetch("/api/meters/bulk", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ thresholds: thresholdData }),
      });

      if (response.ok) {
        setSavedThresholds(true);
        setTimeout(() => setSavedThresholds(false), 2000);
      }
    } catch (error) {
      console.error("Failed to save thresholds:", error);
    } finally {
      setSavingThresholds(false);
    }
  }

  // Reset thresholds to 90% of rated capacity
  function handleResetThresholds() {
    const updated: Record<number, string> = {};
    meters.forEach((m) => {
      if (m.ratedKw) {
        updated[m.id] = Math.round(m.ratedKw * 0.9).toString();
      } else {
        updated[m.id] = (m.maxPowerKw ?? 0).toString();
      }
    });
    setThresholds(updated);
  }

  // Handle single threshold input change
  function handleThresholdChange(id: number, val: string) {
    setThresholds((prev) => ({
      ...prev,
      [id]: val,
    }));
  }

  // Determine status color helper for equipment
  function getEquipStatus(latestReading: Reading | null, maxPowerKw: number | null, ratedKw: number | null) {
    if (!latestReading || maxPowerKw === null) return "normal";
    const kw = latestReading.powerKw;
    if (kw >= maxPowerKw) {
      if (ratedKw && kw >= ratedKw * 0.98) return "critical";
      return "warning";
    }
    return "normal";
  }

  return (
    <div className="grid grid-cols-1 gap-6 lg:grid-cols-3">
      {/* Plant Demand Setpoints */}
      <Card className="lg:col-span-1 h-fit">
        <CardHeader>
          <CardTitle className="font-display">Plant Demand Setpoints</CardTitle>
          <CardDescription>Configure warning and critical alert levels for total plant load</CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleSaveSettings} className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="ratePerKwh">Rate per kWh ($)</Label>
              <Input
                id="ratePerKwh"
                type="number"
                step="0.01"
                value={ratePerKwh}
                onChange={(e) => setRatePerKwh(e.target.value)}
                required
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="alarmSetpoint">Alarm Setpoint (kW)</Label>
              <Input
                id="alarmSetpoint"
                type="number"
                step="1"
                value={alarmSetpointKw}
                onChange={(e) => setAlarmSetpointKw(e.target.value)}
                required
              />
              <span className="text-[11px] text-muted-foreground block">
                Raises a Warning Alert when total load reaches this limit.
              </span>
            </div>
            <div className="space-y-2">
              <Label htmlFor="alertSetpoint">Alert Setpoint (kW)</Label>
              <Input
                id="alertSetpoint"
                type="number"
                step="1"
                value={alertSetpointKw}
                onChange={(e) => setAlertSetpointKw(e.target.value)}
                required
              />
              <span className="text-[11px] text-muted-foreground block">
                Raises a Critical Alert (and fires WhatsApp/Email notification) when reached.
              </span>
            </div>
            <div className="space-y-2">
              <Label htmlFor="capacity">Reference Capacity (kW)</Label>
              <Input
                id="capacity"
                type="number"
                step="1"
                value={referenceCapacityKw}
                onChange={(e) => setReferenceCapacityKw(e.target.value)}
                required
              />
              <span className="text-[11px] text-muted-foreground block">
                Maximum sizing bounds for UI gauges and scales.
              </span>
            </div>
            <div className="flex items-center gap-3 pt-2">
              <Button type="submit" disabled={savingSettings} className="w-full">
                {savingSettings ? "Saving..." : "Save Setpoints"}
              </Button>
              {savedSettings && (
                <div className="flex items-center gap-1 text-emerald-500 text-xs font-semibold animate-in fade-in zoom-in-95 duration-200">
                  <CheckCircle2 className="h-4 w-4" /> Saved
                </div>
              )}
            </div>
          </form>
        </CardContent>
      </Card>

      {/* Per-Equipment Notification Thresholds */}
      <Card className="lg:col-span-2">
        <CardHeader>
          <CardTitle className="font-display">Per-Equipment Notification Thresholds</CardTitle>
          <CardDescription>
            Modify alarm limits (Notify Above kW) for individual downstream equipment.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="rounded-md border overflow-x-auto">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Equipment</TableHead>
                  <TableHead className="text-right">Rated (kW)</TableHead>
                  <TableHead className="text-right">Current (kW)</TableHead>
                  <TableHead className="w-32">Notify Above (kW)</TableHead>
                  <TableHead>Status</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {meters.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={5} className="text-center text-muted-foreground py-6">
                      No equipment meters found in database.
                    </TableCell>
                  </TableRow>
                ) : (
                  meters.map((meter) => {
                    const currentKw = meter.latestReading?.powerKw ?? 0;
                    const maxKw = parseFloat(thresholds[meter.id] || "0");
                    const status = getEquipStatus(meter.latestReading, maxKw, meter.ratedKw);
                    const statusBadge =
                      status === "critical" ? (
                        <Badge variant="destructive">Alert</Badge>
                      ) : status === "warning" ? (
                        <Badge className="bg-amber-500 hover:bg-amber-600 text-white">Alarm</Badge>
                      ) : (
                        <Badge variant="secondary" className="text-emerald-500 bg-emerald-500/10">Normal</Badge>
                      );

                    return (
                      <TableRow key={meter.id}>
                        <TableCell className="font-medium">
                          <div>{meter.name}</div>
                          <span className="text-[10px] text-muted-foreground uppercase font-mono-ems block">
                            {meter.feeder} · {meter.bus}
                          </span>
                        </TableCell>
                        <TableCell className="text-right font-mono-ems">{meter.ratedKw ?? "--"}</TableCell>
                        <TableCell className="text-right font-mono-ems font-semibold text-[var(--accent-cyan)]">
                          {currentKw.toFixed(1)}
                        </TableCell>
                        <TableCell>
                          <Input
                            type="number"
                            className="h-8 font-mono-ems text-xs"
                            value={thresholds[meter.id] || ""}
                            onChange={(e) => handleThresholdChange(meter.id, e.target.value)}
                          />
                        </TableCell>
                        <TableCell>{statusBadge}</TableCell>
                      </TableRow>
                    );
                  })
                )}
              </TableBody>
            </Table>
          </div>

          <div className="flex flex-wrap items-center gap-3 pt-2">
            <Button onClick={handleSaveThresholds} disabled={savingThresholds || meters.length === 0}>
              {savingThresholds ? "Saving..." : "Save All Thresholds"}
            </Button>
            <Button
              variant="outline"
              size="sm"
              onClick={handleResetThresholds}
              disabled={meters.length === 0}
              className="flex items-center gap-1.5 text-xs"
            >
              <RefreshCw className="h-3 w-3" />
              Reset to 90% of Rated
            </Button>
            {savedThresholds && (
              <div className="flex items-center gap-1 text-emerald-500 text-xs font-semibold animate-in fade-in zoom-in-95 duration-200">
                <CheckCircle2 className="h-4 w-4" /> Saved Successfully
              </div>
            )}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

