import { prisma } from "@/lib/prisma";

async function main() {
  // Clear old data
  await prisma.notificationLog.deleteMany();
  await prisma.alert.deleteMany();
  await prisma.reading.deleteMany();
  await prisma.meter.deleteMany();

  // Create Settings singleton
  await prisma.settings.upsert({
    where: { id: 1 },
    update: {},
    create: {
      id: 1,
      ratePerKwh: 8.5,
      alarmSetpointKw: 1400.0,
      alertSetpointKw: 1450.0,
      referenceCapacityKw: 1500.0,
    },
  });

  // Seed Meters
  const metersData = [
    { code: "TR-1", name: "Incomer Transformer 1", type: "transformer" as const, bus: "BUS-1", feeder: null, ratedKw: 1700, maxPowerKw: 1450, location: "Main Substation Sub-1", status: "active" as const },
    { code: "TR-2", name: "Incomer Transformer 2", type: "transformer" as const, bus: "BUS-2", feeder: null, ratedKw: 1700, maxPowerKw: 1450, location: "Main Substation Sub-2", status: "active" as const },

    { code: "CH-1", name: "Chiller 1", type: "equipment" as const, bus: "TR-1", feeder: "F1", ratedKw: 350, maxPowerKw: 315, location: "Utility Building", status: "active" as const },
    { code: "ACP-1", name: "Air Compressor 1", type: "equipment" as const, bus: "TR-1", feeder: "F3", ratedKw: 132, maxPowerKw: 119, location: "Compressor Room", status: "active" as const },
    { code: "CT-1", name: "Cooling Tower Fan 1", type: "equipment" as const, bus: "TR-1", feeder: "F5", ratedKw: 45, maxPowerKw: 41, location: "Cooling Tower Roof", status: "active" as const },
    { code: "AHU-1", name: "Air Handling Unit", type: "equipment" as const, bus: "TR-1", feeder: "F7", ratedKw: 75, maxPowerKw: 68, location: "Main Office AHU Room", status: "active" as const },
    { code: "PP-1", name: "Process Water Pump 1", type: "equipment" as const, bus: "TR-1", feeder: "F9", ratedKw: 110, maxPowerKw: 99, location: "Pump House", status: "active" as const },
    { code: "LDB-1", name: "Lighting Distribution Board", type: "equipment" as const, bus: "TR-1", feeder: "F11", ratedKw: 60, maxPowerKw: 54, location: "Ground Floor Panel", status: "active" as const },

    { code: "CH-2", name: "Chiller 2", type: "equipment" as const, bus: "TR-2", feeder: "F2", ratedKw: 350, maxPowerKw: 315, location: "Utility Building", status: "active" as const },
    { code: "ACP-2", name: "Air Compressor 2", type: "equipment" as const, bus: "TR-2", feeder: "F4", ratedKw: 132, maxPowerKw: 119, location: "Compressor Room", status: "offline" as const },
    { code: "CT-2", name: "Cooling Tower Fan 2", type: "equipment" as const, bus: "TR-2", feeder: "F6", ratedKw: 45, maxPowerKw: 41, location: "Cooling Tower Roof", status: "maintenance" as const },
    { code: "BFP-1", name: "Boiler Feed Pump", type: "equipment" as const, bus: "TR-2", feeder: "F8", ratedKw: 90, maxPowerKw: 81, location: "Boiler House", status: "active" as const },
    { code: "PP-2", name: "Process Water Pump 2", type: "equipment" as const, bus: "TR-2", feeder: "F10", ratedKw: 110, maxPowerKw: 99, location: "Pump House", status: "active" as const },
    { code: "PL-1", name: "Production Line Motor Panel", type: "equipment" as const, bus: "TR-2", feeder: "F12", ratedKw: 180, maxPowerKw: 162, location: "Shop Floor", status: "active" as const },
  ];

  const dbMeters = [];
  for (const m of metersData) {
    const dbMeter = await prisma.meter.create({ data: m });
    dbMeters.push(dbMeter);
  }

  const readingData = [];
  const now = Date.now();
  const oneHourMs = 60 * 60 * 1000;

  // Let's create base values for each active equipment meter to generate consistent history
  const equipMeters = dbMeters.filter((m) => m.type === "equipment");
  const transMeters = dbMeters.filter((m) => m.type === "transformer");

  // Keep track of power generated for each hour to aggregate it for the transformers
  const powerMapByHour: Record<number, Record<string, number>> = {};
  for (let hoursAgo = 47; hoursAgo >= 0; hoursAgo--) {
    powerMapByHour[hoursAgo] = { "TR-1": 0, "TR-2": 0 };
  }

  // Equipment readings
  for (const meter of equipMeters) {
    if (meter.status !== "active") continue;

    // Load base details
    const rated = meter.ratedKw ?? 100;
    const baseLoadFactor = 0.65 + Math.random() * 0.15; // 65% to 80% typical loading
    const pfBase = 0.85 + Math.random() * 0.1; // 0.85 to 0.95 PF
    let cumulativeEnergy = 500.0 + Math.random() * 2000.0;

    for (let hoursAgo = 47; hoursAgo >= 0; hoursAgo--) {
      // Add drift/sinusoidal fluctuation to make trend graphs look realistic
      const drift = 0.05 * Math.sin((hoursAgo / 6) * Math.PI);
      const loadFactor = Math.min(1.0, Math.max(0.4, baseLoadFactor + drift + (Math.random() - 0.5) * 0.05));
      const powerKw = Number((rated * loadFactor).toFixed(3));
      const voltage = Number((415 + (Math.random() - 0.5) * 5).toFixed(2));
      const pf = Math.min(0.99, Math.max(0.75, pfBase + (Math.random() - 0.5) * 0.02));
      const current = Number(((powerKw * 1000) / (Math.sqrt(3) * voltage * pf)).toFixed(2));

      cumulativeEnergy += powerKw; // 1 hr at powerKw adds powerKw kWh

      readingData.push({
        meterId: meter.id,
        voltage,
        current,
        powerKw,
        energyKwh: Number(cumulativeEnergy.toFixed(3)),
        recordedAt: new Date(now - hoursAgo * oneHourMs),
      });

      // Track how much power this equipment draws under its transformer bus
      const busId = meter.bus === "TR-1" ? "TR-1" : "TR-2";
      powerMapByHour[hoursAgo][busId] += powerKw;
    }
  }

  // Transformer readings (aggregate equipment power + 1.5% transformer losses)
  for (const meter of transMeters) {
    let cumulativeEnergy = 5000.0 + Math.random() * 10000.0;
    const pfBase = 0.88;

    for (let hoursAgo = 47; hoursAgo >= 0; hoursAgo--) {
      const activeEquipPower = powerMapByHour[hoursAgo][meter.code ?? ""] ?? 200.0;
      // Transformer total load is equipment load + 1.5% core/copper losses
      const powerKw = Number((activeEquipPower * 1.015).toFixed(3));
      const voltage = Number((415 + (Math.random() - 0.5) * 3).toFixed(2));
      const pf = Math.min(0.99, Math.max(0.82, pfBase + (Math.random() - 0.5) * 0.01));
      const current = Number(((powerKw * 1000) / (Math.sqrt(3) * voltage * pf)).toFixed(2));

      cumulativeEnergy += powerKw;

      readingData.push({
        meterId: meter.id,
        voltage,
        current,
        powerKw,
        energyKwh: Number(cumulativeEnergy.toFixed(3)),
        recordedAt: new Date(now - hoursAgo * oneHourMs),
      });
    }
  }

  await prisma.reading.createMany({ data: readingData });

  console.log(`Seeded ${dbMeters.length} meters and ${readingData.length} readings successfully.`);
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(() => prisma.$disconnect());

